-- Profiles Policies
CREATE POLICY "Profiles viewable by authenticated users" ON claims.profiles
    FOR SELECT TO authenticated USING (true);

CREATE POLICY "Users can update own profile" ON claims.profiles
    FOR UPDATE TO authenticated USING (auth.uid() = id);

CREATE POLICY "Admins can manage all profiles" ON claims.profiles
    FOR ALL TO authenticated USING (claims.is_admin(auth.uid()));

-- Master Data Read Policies (Ministries, Categories, Cost Centres, Roles)
CREATE POLICY "Ministries viewable by all authenticated" ON claims.ministries FOR SELECT TO authenticated USING (true);
CREATE POLICY "Ministries manageable by admin" ON claims.ministries FOR ALL TO authenticated USING (claims.is_admin(auth.uid()));

CREATE POLICY "Categories viewable by all authenticated" ON claims.expense_categories FOR SELECT TO authenticated USING (true);
CREATE POLICY "Categories manageable by admin" ON claims.expense_categories FOR ALL TO authenticated USING (claims.is_admin(auth.uid()));

CREATE POLICY "Cost centres viewable by all authenticated" ON claims.cost_centres FOR SELECT TO authenticated USING (true);
CREATE POLICY "Cost centres manageable by admin" ON claims.cost_centres FOR ALL TO authenticated USING (claims.is_admin(auth.uid()));

CREATE POLICY "Roles viewable by all authenticated" ON claims.roles FOR SELECT TO authenticated USING (true);
CREATE POLICY "User roles viewable by all authenticated" ON claims.user_roles FOR SELECT TO authenticated USING (true);
CREATE POLICY "User roles manageable by admin" ON claims.user_roles FOR ALL TO authenticated USING (claims.is_admin(auth.uid()));

-- Claims Policies (Strict RBAC)
CREATE POLICY "Claimants can view own claims" ON claims.claims
    FOR SELECT TO authenticated
    USING (
        claimant_id = auth.uid()
        OR claims.has_role(auth.uid(), 'FINANCE_OFFICER')
        OR claims.has_role(auth.uid(), 'FINAL_APPROVER')
        OR claims.has_role(auth.uid(), 'SYSTEM_ADMIN')
        OR EXISTS (
            SELECT 1 FROM claims.ministries m 
            WHERE m.id = claims.ministry_id AND m.leader_id = auth.uid()
        )
    );

CREATE POLICY "Claimants can create draft claims" ON claims.claims
    FOR INSERT TO authenticated
    WITH CHECK (claimant_id = auth.uid());

CREATE POLICY "Claimants can update own drafts or returned claims" ON claims.claims
    FOR UPDATE TO authenticated
    USING (
        (claimant_id = auth.uid() AND status IN ('DRAFT', 'RETURNED_FOR_CLARIFICATION'))
        OR claims.has_role(auth.uid(), 'FINANCE_OFFICER')
        OR claims.has_role(auth.uid(), 'SYSTEM_ADMIN')
    );

CREATE POLICY "Claimants can delete own drafts" ON claims.claims
    FOR DELETE TO authenticated
    USING (claimant_id = auth.uid() AND status = 'DRAFT');

-- Claim Expenses Policies
CREATE POLICY "Users can view expenses of viewable claims" ON claims.claim_expenses
    FOR SELECT TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM claims.claims c 
            WHERE c.id = claim_expenses.claim_id 
              AND (
                  c.claimant_id = auth.uid()
                  OR claims.has_role(auth.uid(), 'FINANCE_OFFICER')
                  OR claims.has_role(auth.uid(), 'FINAL_APPROVER')
                  OR claims.has_role(auth.uid(), 'SYSTEM_ADMIN')
                  OR EXISTS (SELECT 1 FROM claims.ministries m WHERE m.id = c.ministry_id AND m.leader_id = auth.uid())
              )
        )
    );

CREATE POLICY "Claimants can manage expenses for own draft/returned claims" ON claims.claim_expenses
    FOR ALL TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM claims.claims c 
            WHERE c.id = claim_expenses.claim_id 
              AND c.claimant_id = auth.uid() 
              AND c.status IN ('DRAFT', 'RETURNED_FOR_CLARIFICATION')
        )
    );

-- Claim Attachments Policies
CREATE POLICY "Users can view attachments of viewable claims" ON claims.claim_attachments
    FOR SELECT TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM claims.claims c 
            WHERE c.id = claim_attachments.claim_id 
              AND (
                  c.claimant_id = auth.uid()
                  OR claims.has_role(auth.uid(), 'FINANCE_OFFICER')
                  OR claims.has_role(auth.uid(), 'FINAL_APPROVER')
                  OR claims.has_role(auth.uid(), 'SYSTEM_ADMIN')
                  OR EXISTS (SELECT 1 FROM claims.ministries m WHERE m.id = c.ministry_id AND m.leader_id = auth.uid())
              )
        )
    );

CREATE POLICY "Claimants can insert attachments to own claims" ON claims.claim_attachments
    FOR INSERT TO authenticated
    WITH CHECK (uploaded_by = auth.uid());

CREATE POLICY "Claimants can delete attachments from drafts" ON claims.claim_attachments
    FOR DELETE TO authenticated
    USING (
        uploaded_by = auth.uid() 
        AND EXISTS (SELECT 1 FROM claims.claims c WHERE c.id = claim_attachments.claim_id AND c.status IN ('DRAFT', 'RETURNED_FOR_CLARIFICATION'))
    );

-- Notifications Policy
CREATE POLICY "Users can view their own notifications" ON claims.notifications
    FOR SELECT TO authenticated USING (user_id = auth.uid());

CREATE POLICY "Users can update their own notifications" ON claims.notifications
    FOR UPDATE TO authenticated USING (user_id = auth.uid());

-- Audit Logs Policy
CREATE POLICY "Audit logs viewable by Finance and Admins" ON claims.audit_logs
    FOR SELECT TO authenticated
    USING (claims.has_role(auth.uid(), 'FINANCE_OFFICER') OR claims.is_admin(auth.uid()));

CREATE POLICY "Audit logs insertable by authenticated users" ON claims.audit_logs
    FOR INSERT TO authenticated WITH CHECK (true);
